const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x);
const button=(attrs,label,on=false)=>`<button type="button" class="${on?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
let visit=null,binding=0;
const kitchenEntry=()=>button('data-lk-entry',kitchenCopy.entry);
const pollenEntry=()=>button('data-pollen-path-entry','Follow a pollen path');
const exchangeEntry=()=>button('data-leaf-exchange-entry','Compare a leaf’s gas accounts');
// Copy only the kept model's display fields; this is not a new learner record.
function captureExchangeContext(book){
 const last=lastDiffusionRun(book);if(!last)return null;
 const {raw,index}=last,counts=diffusionCounts(raw.source,raw.work);if(!counts)return null;
 const rows=counts.map(c=>Object.freeze({label:c.label,canCross:raw.source.kinds.find(k=>k.id===c.kindId).canCross,leftToRight:c.leftToRight,rightToLeft:c.rightToLeft,net:c.net}));
 return Object.freeze({index,title:raw.source.title,notice:raw.source.notice,steps:raw.work.steps,rows:Object.freeze(rows)});
}

// A return frame watches the actual waiting guide, not a saved kitchen schema.
function parentFrame(v){const s=slot(v),raw=v.screen==='card'?layerGuidesView(v.book).items.find(x=>x.id===v.card)?.raw:null;return {raw,screen:v.screen,active:v.active,card:v.card,slot:s,source:s?.source,work:s?.work,rawSource:raw?.source,rawWork:raw?.work,display:JSON.stringify([v.shelfPage,v.chooser,s?.camera,s?.turn,s?.current,s?.folds,s?.status,s?.source,s?.work,raw?.source,raw?.work,raw])};}
const sameFrame=(a,b)=>!!a&&Object.keys(a).every(k=>a[k]===b[k]);
function currentChild(v){
 if(v.child&&!sameFrame(v.childFrame,parentFrame(v))){
  if(v.pollenWork)v.pollenWork=changePollenPath(v.pollenWork,'fresh-cancel');
  v.child=null;v.pollenAnnounce=false;
 }
 return v.child;
}
// A retired control cannot regain authority by being reattached or unhidden.
function bindingGuard(root,valid){
 const controls=[root,...root.querySelectorAll('button,select,details,summary,a,[data-speak],#pollen-path-status')];
 const retired=new WeakSet(),chains=new Map();
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};
 controls.forEach(n=>chains.set(n,chain(n)));
 const retire=records=>{for(const r of records){
  if(r.type==='attributes'){
   if(r.target.closest?.('.speech-controls'))continue;
   for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);
  }else for(const removed of r.removedNodes)for(const n of controls)
   if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);
 }};
 const observer=new MutationObserver(records=>{retire(records);if(!root.isConnected)observer.disconnect();});
 observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return n=>{
  retire(observer.takeRecords());
  if(!valid()||!root.isConnected||!root.contains(n)||retired.has(n))return false;
  const old=chains.get(n),now=chain(n);
  if(!old||old.length!==now.length||!old.every((p,i)=>p===now[i]))return false;
  for(let p=n;p?.nodeType===1;p=p.parentElement){
   if(p.hidden||p.inert||p.getAttribute('aria-hidden')==='true')return false;
   const c=getComputedStyle(p);if(c.display==='none'||c.visibility==='hidden'||c.visibility==='collapse')return false;
  }
  return n.getClientRects().length>0;
 };
}

export function resetLivingLayers(){visit=null;binding++;}
function state(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,screen:'draft',active:layerCases[0].id,card:null,slots:new Map(),copies:new Map(),readonly:new Map(),shelfPage:null,chooser:false,exchangeCaptured:false};return visit;}
function makeSlot(source,work){return {source:clone(source),work:clone(work||newLayerWork(source)),turn:0,camera:source.nodes.at(-1).id,current:null,folds:{},status:''};}
const slot=v=>v.screen==='card'?v.readonly.get(v.card):v.copies.get(v.active)||v.slots.get(v.active);
function draft(v,id){const source=layerSource(id);if(!source)return;if(!v.slots.has(id))v.slots.set(id,makeSlot(source));v.active=id;v.screen='draft';}
const node=(s,id)=>s.nodes.find(n=>n.id===id);
